use std::io;

fn main() {
    let a = [1, 2, 3, 4, 5];
    let mut index = String::new();
    io::stdin().read_line(&mut index).expect("Failed to read line");
    let index = index.trim().parse::<usize>().expect("Invalid index");

    let element = a[index];

    println!("The value of element is: {}", element);
